(function setup() {
  const g = window.__game;
  if (!g) return 'window.__game missing: add &debug to --query';
  const bus = g.events;
  if (!bus.__qaSwallow) {
    // headless Chromium cannot hold pointer lock: drop {locked:false} so Game does not pause the run
    const emit = bus.emit;
    bus.__qaSwallow = true;
    bus.emit = function (n, p) { if (n === 'input:pointerlock' && p && p.locked === false) return undefined; return emit.call(this, n, p); };
  }
  const D = Math.PI / 180;
  // wait N seconds of GAME time (software GL is slow: wall time is meaningless), capped in wall time
  window.__qaWaitGame = (sec) => new Promise((res) => {
    const t0 = g.realTime, r0 = performance.now(), cap = Math.max(20000, sec * 40000);
    const iv = setInterval(() => { if (g.realTime - t0 >= sec || performance.now() - r0 > cap) { clearInterval(iv); res(); } }, 30);
  });
  window.__qaWaitUntil = (fn, sec) => new Promise((res) => {
    const t0 = g.realTime, r0 = performance.now(), cap = Math.max(20000, sec * 40000);
    const iv = setInterval(() => {
      let ok = false;
      try { ok = !!fn(); } catch (_) { ok = false; }
      if (ok || g.realTime - t0 >= sec || performance.now() - r0 > cap) { clearInterval(iv); res(ok); }
    }, 50);
  });
  // exact debug camera: the player is teleported there (systems stay consistent) and the camera is overridden
  window.__qaCam = (x, y, z, yawDeg, pitchDeg, fov = 70) => {
    const gy = g.world.groundHeightAt(x, z, y - 1.62);
    g.player.teleport(x, gy, z, yawDeg * D, pitchDeg * D);
    g.player.cameraOverride = true;
    g.camera.position.set(x, y, z);
    g.camera.rotation.set(pitchDeg * D, yawDeg * D, 0, 'YXZ');
    if (g.camera.fov !== fov) { g.camera.fov = fov; g.camera.updateProjectionMatrix(); }
    g.camera.updateMatrixWorld(true);
    return `cam ${x},${y},${z} yaw ${yawDeg} pitch ${pitchDeg} fov ${fov}`;
  };
  window.__qaLight = (power, flashlight) => {
    if (g.world.power !== power) g.world.setPower(power);
    if (flashlight) { if (!g.player.flashlight.has) g.player.giveFlashlight(); g.player.setFlashlightOn(true); } else if (g.player.flashlight.on) g.player.setFlashlightOn(false);
    return `power ${power} flashlight ${flashlight}`;
  };
  window.__qaClick = (re) => {
    const rx = new RegExp(re, 'i');
    for (const el of document.querySelectorAll('button, [role="button"], a, [data-action]')) {
      const t = [el.textContent, el.getAttribute('aria-label'), el.getAttribute('title')].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim();
      const r = el.getBoundingClientRect();
      if (rx.test(t) && r.width > 1 && r.height > 1 && getComputedStyle(el).visibility !== 'hidden') { el.click(); return `clicked "${t.slice(0, 30)}"`; }
    }
    return `no visible button /${re}/`;
  };
  // freeze the scenario script (blowout timer, scares, hints) so views are deterministic
  window.__qaFreeze = () => { if (g.puzzles && !g.puzzles.__qaFrozen) { g.puzzles.__qaFrozen = true; g.puzzles.update = function () {}; } return 'puzzles frozen'; };
  window.__qaCloset = async () => {
    const s = (g.world.hideSpots || []).find((h) => h.id === 'closet');
    if (!s) return 'no closet hide spot';
    const door = s.door && s.door.object ? s.door : g.world.handles['door.closet']; // see playtest api.hideSpot.door
    const spot = { ...s, door };
    g.player.cameraOverride = false;
    g.player.teleport(s.exitPos.x, 0, s.exitPos.z, Math.PI / 2, 0);
    await window.__qaWaitGame(0.3);
    try { g.player.enterHide(spot); } catch (e) { return 'enterHide threw: ' + e.message; }
    await window.__qaWaitUntil(() => g.player.hidden, 4);
    await window.__qaWaitGame(1.2);
    const c = g.camera.position;
    if (Math.hypot(c.x - s.hidePos.x, c.z - s.hidePos.z) > 0.35) {
      window.__qaCam(s.hidePos.x, s.hidePos.y, s.hidePos.z, s.hideYaw / D, 0);
      return 'FALLBACK camera at hidePos: player.enterHide did not move the camera (stub?)';
    }
    return 'hidden=' + g.player.hidden;
  };
  return `qa helpers ready; state=${g.state} stage=${g.puzzles && g.puzzles.stage} entity=${g.entity && g.entity.state}`;
})()
